import{_ as a,o as i,c as t,ag as l}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"Teacher Dashboard -> Profile Availability & Calendar (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/profile-availability-calendar.md","filePath":"modules/teacher-dashboard/profile-availability-calendar.md"}'),d={name:"modules/teacher-dashboard/profile-availability-calendar.md"};function o(r,e,s,n,c,h){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="teacher-dashboard-profile-availability-calendar-deep" tabindex="-1">Teacher Dashboard -&gt; Profile Availability &amp; Calendar (deep) <a class="header-anchor" href="#teacher-dashboard-profile-availability-calendar-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Profile Availability &amp; Calendar (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>profile-availability-calendar</code><br><strong>Surface:</strong> Availability &amp; Calendar tab inside <code>/teacher-dashboard/settings</code></p><p>This tab is where instructors publish and manage available lesson slots.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Display availability by day and slot count.</li><li>Add future availability slots.</li><li>Delete availability slots.</li><li>Prevent slot publishing until Stripe onboarding is verified and active.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/AvailabilityTab.tsx</code></td><td>Main availability UI</td><td>Uses MUI calendars and time pickers; calls availability GraphQL and checks teacher Stripe readiness.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/AvailabilityCalendar.tsx</code></td><td>Overview reuse</td><td>Shows availability summary from the same backend module on the overview page.</td></tr><tr><td><code>Frontend/src/graphql/mutations/availability.ts</code></td><td>Availability GraphQL</td><td>Defines query and mutations used by the tab.</td></tr><tr><td><code>Frontend/src/graphql/mutations/profile.ts</code></td><td>Teacher profile query</td><td>Provides Stripe onboarding status used to gate slot creation.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="availability-operations" tabindex="-1">Availability operations <a class="header-anchor" href="#availability-operations" aria-label="Permalink to &quot;Availability operations&quot;">​</a></h3><ul><li><code>GET_TEACHER_AVAILABILITY</code><ul><li>Query field: <code>teacherAvailability(month: String!)</code></li><li>Used by: <ul><li><code>AvailabilityTab.tsx</code></li><li>overview calendar component</li></ul></li></ul></li><li><code>ADD_AVAILABILITY_SLOT</code><ul><li>Mutation field: <code>addAvailabilitySlot(input: TeacherAvailabilityInput!)</code></li><li>Used by <code>AvailabilityTab.tsx</code></li></ul></li><li><code>DELETE_AVAILABILITY_SLOT</code><ul><li>Mutation field: <code>deleteAvailabilitySlot(id: ID!)</code></li><li>Used by <code>AvailabilityTab.tsx</code></li></ul></li></ul><h3 id="stripe-readiness-dependency" tabindex="-1">Stripe readiness dependency <a class="header-anchor" href="#stripe-readiness-dependency" aria-label="Permalink to &quot;Stripe readiness dependency&quot;">​</a></h3><ul><li><code>GET_TEACHER_PROFILE</code><ul><li>Used in <code>AvailabilityTab.tsx</code></li><li>Checks <code>onboardingStatus</code> and <code>isActive</code></li><li>Prevents adding slots when payments are not ready</li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/availability.js</code></li><li>Relevant query: <ul><li><code>teacherAvailability(month: String!): [TeacherAvailability!]!</code></li></ul></li><li>Relevant mutations: <ul><li><code>addAvailabilitySlot</code></li><li><code>deleteAvailabilitySlot</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/availability.resolver.js</code></li><li>Relevant resolvers: <ul><li><code>Query.teacherAvailability</code></li><li><code>Mutation.addAvailabilitySlot</code></li><li><code>Mutation.deleteAvailabilitySlot</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/teacherAvailability.model.js</code></td><td>Stores availability dates and slots</td></tr><tr><td><code>server/src/graphql/utils/instructorPaymentReady.js</code></td><td>Shared payment-readiness gating logic</td></tr><tr><td><code>server/src/models/User.js</code></td><td>Source of onboarding and active-payment state</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens Availability tab.</li><li>Tab loads <code>teacherAvailability(month)</code> for the currently viewed month.</li><li>Tab also loads <code>teacherProfile</code> to compute <code>isPaymentReady</code>.</li><li>If Stripe is not ready, Add Slot actions are blocked with a toast.</li><li>Adding a slot calls <code>addAvailabilitySlot</code>.</li><li>Deleting a slot calls <code>deleteAvailabilitySlot</code>.</li><li>Both mutations refetch availability so the calendar badges and slot list remain current.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This module is used both in the settings tab and in the overview dashboard summary widget.</li><li>The UI blocks past dates and invalid time ranges before the mutation is sent.</li></ul>',23)])])}const p=a(d,[["render",o]]);export{u as __pageData,p as default};
